function validate(input) {
  const [{ Sales = [] }] = input;
  const ids = new Set();
  for (const [id, name, date] of Sales) {
    if (id === null) return 'Every sale needs a sale_id.';
    if (ids.has(id)) return `sale_id ${id} appears twice in Sales.`;
    ids.add(id);
    if (name === null || name.trim() === '') return `Sale ${id} needs a product_name.`;
    if (date === null) return `Sale ${id} needs a sale_date.`;
  }
  return null;
}

