function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const small = size === 'small';
  const products = ['LCPhone', 'LCKeyChain', 'Matryoshka', 'LC Phone', 'Teapot'];
  if (!small) for (let k = 1; k <= 30; k++) products.push(`Gadget ${k}`);
  const months = small
    ? ['1999-12', '2000-01', '2000-02', '2000-03', '2001-01']
    : Array.from({ length: 36 }, (_, i) => `${1999 + Math.floor(i / 12)}-${String(i % 12 + 1).padStart(2, '0')}`);
  const days = small ? ['01', '16', '28'] : Array.from({ length: 28 }, (_, i) => String(i + 1).padStart(2, '0'));
  // Each name gets a random letter case and up to two spaces on either side.
  const mangle = name => {
    const cased = [...name].map(ch => (rand() < 0.5 ? ch.toUpperCase() : ch.toLowerCase())).join('');
    return ' '.repeat(Math.floor(rand() * 3)) + cased + ' '.repeat(Math.floor(rand() * 3));
  };
  const count = small ? Math.floor(rand() * 9) : 2000;
  const Sales = [];
  for (let id = 1; id <= count; id++) Sales.push([id, mangle(pick(products)), `${pick(months)}-${pick(days)}`]);
  return [{ Sales }];
}
